CREATE TYPE public.app_role AS ENUM ('admin','client');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', blocked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_blocked(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT blocked FROM public.profiles WHERE id=_user_id),false) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role),public.is_blocked(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.is_blocked(uuid) TO authenticated,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid() AND NOT blocked);
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,phone,email) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',''),COALESCE(NEW.raw_user_meta_data->>'phone',''),COALESCE(NEW.email,'')) ON CONFLICT(id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'client') ON CONFLICT DO NOTHING; IF NEW.email_confirmed_at IS NOT NULL AND lower(COALESCE(NEW.email,''))='mezie707@gmail.com' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TRIGGER on_auth_user_confirmed AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW WHEN(OLD.email_confirmed_at IS NULL AND NEW.email_confirmed_at IS NOT NULL) EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.guard_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.blocked IS DISTINCT FROM OLD.blocked AND NOT public.has_role(auth.uid(),'admin') THEN NEW.blocked=OLD.blocked; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER guard_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile();
CREATE TABLE public.cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,amount_lost numeric NOT NULL DEFAULT 0,asset_type text NOT NULL DEFAULT 'Other',wallet_address text,transaction_reference text,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'under_review',amount_recovered numeric NOT NULL DEFAULT 0,admin_note text NOT NULL DEFAULT '',case_number bigint GENERATED ALWAYS AS IDENTITY(START WITH 1000000 MINVALUE 1000000 MAXVALUE 9999999) UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cases TO authenticated; GRANT ALL ON public.cases TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.cases_case_number_seq TO authenticated,service_role;
ALTER TABLE public.cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY cases_read ON public.cases FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY cases_insert ON public.cases FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_blocked(auth.uid()) AND status='under_review' AND amount_recovered=0 AND admin_note='');
CREATE POLICY cases_update ON public.cases FOR UPDATE TO authenticated USING((user_id=auth.uid() AND NOT public.is_blocked(auth.uid())) OR public.has_role(auth.uid(),'admin')) WITH CHECK((user_id=auth.uid() AND NOT public.is_blocked(auth.uid())) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY cases_delete ON public.cases FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,last_message_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_read ON public.conversations FOR SELECT TO authenticated USING(client_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY conversations_insert ON public.conversations FOR INSERT TO authenticated WITH CHECK(client_id=auth.uid());
CREATE POLICY conversations_update ON public.conversations FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES public.profiles(id),sender_role public.app_role NOT NULL,body text NOT NULL DEFAULT '',attachment_path text,attachment_name text,attachment_type text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX messages_conversation_created_idx ON public.messages(conversation_id,created_at);
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.client_id=auth.uid()));
CREATE POLICY messages_insert ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND ((sender_role='admin' AND public.has_role(auth.uid(),'admin')) OR (sender_role='client' AND NOT public.is_blocked(auth.uid()) AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.client_id=auth.uid()))));
CREATE POLICY messages_update ON public.messages FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.client_id=auth.uid()));
CREATE FUNCTION public.guard_message_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND (NEW.id,NEW.conversation_id,NEW.sender_id,NEW.sender_role,NEW.body,NEW.attachment_path,NEW.attachment_name,NEW.attachment_type,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.conversation_id,OLD.sender_id,OLD.sender_role,OLD.body,OLD.attachment_path,OLD.attachment_name,OLD.attachment_type,OLD.created_at) THEN RAISE EXCEPTION 'Only read status can be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER messages_guard_update BEFORE UPDATE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_message_update();
CREATE FUNCTION public.touch_conversation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.conversations SET last_message_at=NEW.created_at WHERE id=NEW.conversation_id; RETURN NEW; END $$;
CREATE TRIGGER messages_touch_conversation AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.touch_conversation();
CREATE TABLE public.case_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,storage_path text NOT NULL,file_name text NOT NULL DEFAULT '',file_type text NOT NULL DEFAULT '',caption text NOT NULL DEFAULT '',uploaded_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.case_attachments TO authenticated; GRANT ALL ON public.case_attachments TO service_role;
ALTER TABLE public.case_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY attachments_read ON public.case_attachments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cases c WHERE c.id=case_id AND c.user_id=auth.uid()));
CREATE POLICY attachments_insert ON public.case_attachments FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cases c WHERE c.id=case_id AND c.user_id=auth.uid())));
CREATE POLICY attachments_update ON public.case_attachments FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY attachments_delete ON public.case_attachments FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.case_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,status text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.case_events TO authenticated; GRANT ALL ON public.case_events TO service_role;
ALTER TABLE public.case_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.case_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cases c WHERE c.id=case_id AND c.user_id=auth.uid()));
CREATE POLICY events_insert ON public.case_events FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.guard_case_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND (NEW.user_id,NEW.amount_recovered,NEW.admin_note,NEW.case_number) IS DISTINCT FROM (OLD.user_id,OLD.amount_recovered,OLD.admin_note,OLD.case_number) THEN RAISE EXCEPTION 'Recovery fields require administrator access'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status<>'cancelled' THEN RAISE EXCEPTION 'Status changes require administrator access'; END IF; NEW.updated_at=now(); IF NEW.status IN ('recovered','resolved') AND OLD.status IS DISTINCT FROM NEW.status THEN NEW.resolved_at=now(); ELSIF NEW.status NOT IN ('recovered','resolved') THEN NEW.resolved_at=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER cases_guard_update BEFORE UPDATE ON public.cases FOR EACH ROW EXECUTE FUNCTION public.guard_case_update();
CREATE FUNCTION public.log_case_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.case_events(case_id,status,note) VALUES(NEW.id,NEW.status,'Case filed and received by our team.'); ELSIF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.case_events(case_id,status,note) VALUES(NEW.id,NEW.status,COALESCE(NEW.admin_note,'')); END IF; RETURN NEW; END $$;
CREATE TRIGGER cases_log_event_insert AFTER INSERT ON public.cases FOR EACH ROW EXECUTE FUNCTION public.log_case_event();
CREATE TRIGGER cases_log_event_update AFTER UPDATE OF status ON public.cases FOR EACH ROW EXECUTE FUNCTION public.log_case_event();
REVOKE ALL ON FUNCTION public.guard_profile(),public.guard_message_update(),public.touch_conversation(),public.guard_case_update(),public.log_case_event() FROM PUBLIC,anon,authenticated;
CREATE POLICY chat_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-attachments' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY chat_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-attachments' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY case_files_admin ON storage.objects FOR ALL TO authenticated USING(bucket_id='case-attachments' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='case-attachments' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY case_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='case-attachments' AND EXISTS(SELECT 1 FROM public.case_attachments a JOIN public.cases c ON c.id=a.case_id WHERE a.storage_path=name AND c.user_id=auth.uid()));
CREATE POLICY case_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='case-attachments' AND EXISTS(SELECT 1 FROM public.cases c WHERE c.user_id=auth.uid() AND c.id::text=(storage.foldername(name))[1]));
ALTER TABLE public.messages REPLICA IDENTITY FULL; ALTER TABLE public.conversations REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages,public.conversations;